import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static void add(int[] tree, int i, int delta) {
        for (; i < tree.length; i += i & -i) tree[i] += delta;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long[] values = a.clone();
        Arrays.sort(values);
        int size = 0;
        for (int i = 0; i < n; i++) if (i == 0 || values[i] != values[i - 1]) values[size++] = values[i];
        int[] idx = new int[n];  // 1-based compressed value
        for (int i = 0; i < n; i++) idx[i] = Arrays.binarySearch(values, 0, size, a[i]) + 1;
        // Fenwick tree of value counts in the current window.
        int[] tree = new int[size + 1];
        for (int i = 0; i < m; i++) add(tree, idx[i], 1);
        int top = Integer.highestOneBit(size);
        StringBuilder out = new StringBuilder();
        for (int start = 0; start + m <= n; start++) {
            if (start > 0) {
                add(tree, idx[start - 1], -1);
                add(tree, idx[start + m - 1], 1);
            }
            // Binary lifting: the longest prefix of values holding fewer than k elements.
            int target = k, at = 0;
            for (int step = top; step > 0; step >>= 1) {
                int nxt = at + step;
                if (nxt <= size && tree[nxt] < target) {
                    target -= tree[nxt];
                    at = nxt;
                }
            }
            if (start > 0) out.append(' ');
            out.append(values[at]);
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m, k := int(nextInt()), int(nextInt()), int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	values := slices.Clone(a)
	slices.Sort(values)
	values = slices.Compact(values)
	size := len(values)
	idx := make([]int, n) // 1-based compressed value
	for i, v := range a {
		p, _ := slices.BinarySearch(values, v)
		idx[i] = p + 1
	}
	// Fenwick tree of value counts in the current window.
	tree := make([]int, size+1)
	add := func(i, delta int) {
		for ; i <= size; i += i & -i {
			tree[i] += delta
		}
	}
	for i := 0; i < m; i++ {
		add(idx[i], 1)
	}
	top := 1
	for top*2 <= size {
		top *= 2
	}
	out := make([]byte, 0, 12*(n-m+1))
	for start := 0; start+m <= n; start++ {
		if start > 0 {
			add(idx[start-1], -1)
			add(idx[start+m-1], 1)
		}
		// Binary lifting: the longest prefix of values holding fewer than k elements.
		target, at := k, 0
		for step := top; step > 0; step >>= 1 {
			if nxt := at + step; nxt <= size && tree[nxt] < target {
				target -= tree[nxt]
				at = nxt
			}
		}
		if start > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, values[at], 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
